const fs = require('fs');
const twilio = require('twilio');

// Twilio credentials
const accountSid = 'ACXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX';
const authToken  = 'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX';
const fromNumber = '+13125550100';

// Recipient
const toNumber = '+13125550172';

// Read the onboarding guide verbatim
const messageBody = fs.readFileSync('./docs/onboarding_guide.md', 'utf8');

// Send SMS
const client = twilio(accountSid, authToken);

client.messages
  .create({
    body: messageBody,
    from: fromNumber,
    to: toNumber,
  })
  .then((message) => {
    console.log(`SMS sent successfully! SID: ${message.sid}`);
  })
  .catch((err) => {
    console.error(`Failed to send SMS: ${err.message}`);
  });
